/* eslint-env jest */
'use strict';

const os = require('os');

const yandexLogger = require('../../src');

describe('YandexLogger. Middleware. Request ID', () => {
    let logger;
    let stream;
    let baseRecord;
    let jestFakeTimers;

    beforeEach(() => {
        // Initialize a mock function to replace `write`.
        stream = { write: jest.fn() };

        logger = yandexLogger({
            streams: [
                { stream },
            ],
            middleware: [
                require('../../middleware/request-id')(),
            ],
        });

        baseRecord = {
            pid: process.pid,
            date: expect.any(Date),
            name: 'yandex-logger',
            hostname: os.hostname(),
            level: 30,
            levelName: 'INFO',
            msg: 'message',
            msgFormat: 'message',
            msgArgs: [],
        };

        // Use fake timers and set the system time
        jestFakeTimers = jest.useFakeTimers('modern');
        jest.setSystemTime(1000);
    });

    afterEach(() => {
        jestFakeTimers.clearAllTimers();
    });

    it('должен взять requestId из req.id', () => {
        let req = {
            id: 'req-1',
            requestId: 'req-2',
            headers: {
                'x-request-id': 'req-3',
                'x-req-id': 'req-4',
            },
        };
        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req,
            requestId: 'req-1',
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('должен взять requestId из req.requestId', () => {
        let req = {
            id: null,
            requestId: 'req-2',
            headers: {
                'x-request-id': 'req-3',
                'x-req-id': 'req-4',
            },
        };
        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req,
            requestId: 'req-2',
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('должен взять requestId из заголовка X-Request-Id', () => {
        let req = {
            id: null,
            requestId: null,
            headers: {
                'x-request-id': 'req-3',
                'x-req-id': 'req-4',
            },
        };
        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req,
            requestId: 'req-3',
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('должен взять requestId из заголовка X-Req-Id', () => {
        let req = {
            id: null,
            requestId: null,
            headers: {
                'x-req-id': 'req-4',
            },
        };
        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req,
            requestId: 'req-4',
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('должен взять существующий requestId', () => {
        let req = {
            id: 'id-2',
        };
        logger.info({ req, requestId: 'id-1' }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req,
            requestId: 'id-1',
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('не должен падать без requestId', () => {
        let req = {};
        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req,
            requestId: undefined,
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('не должен падать без record.req', () => {
        logger.info('message');

        expect(stream.write).toHaveBeenCalledWith(baseRecord);
        expect(stream.write).toHaveBeenCalledTimes(1);
    });
});
